floor_fn:
"""
    Subtract ch2 from ch1
    ch2 is first adjusted to m * ch2 + c

    :param ch1:
    :param ch2:
    :param m:
    :param c:
    :return:
    """
def af_subtraction(ch1: Any, ch2: Any, m: Any, c: Any) -> object {
    af = (m * ch2) + c;
    signal = ch1 - af;
    return signal;
}

